-- A rodada diária das 06h40 UTC das campanhas da Shopee falhou hoje sem deixar rastro (o cron só registra o disparo). Segunda rodada no fim da tarde, mesma chamada.
select cron.schedule('ads-sincronizar-campanhas-tarde', '40 20 * * *', $$select net.http_post(url:='https://imlgfmaqmzfonvbmlwpd.supabase.co/functions/v1/ads-sincronizar', headers:=jsonb_build_object('Content-Type','application/json','x-fin-token',(select substr(encode(sha256(convert_to('telegram:'||valor,'UTF8')),'hex'),1,48) from lucro_segredo limit 1)), body:='{"dias":7,"mkt":"shopee","nivel":["campanha"]}'::jsonb, timeout_milliseconds:=150000)$$);
